        static FlowLayoutPanel Flow(){return new FlowLayoutPanel {Dock=DockStyle.Fill,WrapContents=false,Margin=new Padding(0)};}
        void Buttonize(Button b,string text,int width){b.Text=text;b.Size=new Size(width,32);b.Margin=new Padding(0,0,6,4);b.UseVisualStyleBackColor=true;}
        List<string> Selected(){items.EndEdit();return items.Rows.Cast<DataGridViewRow>().Where(r=>Convert.ToBoolean(r.Cells[0].Value)).Select(r=>(string)r.Tag).ToList();}
        void SetSelection(IEnumerable<string> keys){var set=new HashSet<string>(keys);if(Current.provider)settings.SetFlag("confirm_data_absent",set.Contains("no_data_error"));loading=true;foreach(DataGridViewRow r in items.Rows)r.Cells[0].Value=set.Contains((string)r.Tag);loading=false;if(set.Count==1){var row=items.Rows.Cast<DataGridViewRow>().FirstOrDefault(r=>set.Contains((string)r.Tag));if(row!=null)items.CurrentCell=row.Cells[1];}Dirty();}
        void ChooseGroup(){
            if(!Current.provider){SetSelection(Current.tests.Select(t=>t.key));return;}
            var menu=new ContextMenuStrip();menu.Items.Add("정상 자료 · 요청 오류",null,(s,e)=>SetSelection(Current.tests.Where(t=>t.key!="no_data_error"&&t.key!="no_data").Select(t=>t.key)));
            menu.Items.Add("자료 부재 오류",null,(s,e)=>SetSelection(new[]{"no_data_error"}));menu.Items.Add("빈 정상응답",null,(s,e)=>SetSelection(new[]{"no_data"}));menu.Show(all,new Point(0,all.Height));
        }
        void LoadScenario(){if(Current==null)return;loading=true;items.Rows.Clear();foreach(var t in Current.tests){int i=items.Rows.Add(false,t.label,"—","미확인");items.Rows[i].Tag=t.key;}settings.LoadScenario(Current);loading=false;roles.Text="선택한 시험: "+Current+"\r\n시험 대상: "+Current.targetSystem+" · "+Current.targetRole+"\r\n시험 시스템: "+Current.testerSystem+" · "+Current.testerRole;SetSelection(new[]{(Current.tests.FirstOrDefault(t=>t.key.StartsWith("normal_"))??Current.tests[0]).key});address.Clear();outcome=null;lastDirectory=null;completed.Clear();progress.Value=0;log.Clear();status.Text="환경설정과 상세시험을 확인한 뒤 적용하세요.";ReadReviews();Describe();UpdateSelection();}
        void Describe(){if(loading || items.CurrentRow==null || items.CurrentRow.Tag==null || Current==null)return;var t=Current.tests.First(x=>x.key==(string)items.CurrentRow.Tag);detail.Text=t.description+"\r\n기대 결과: "+LabelState(t.expected);}
        void Dirty(){if(loading)return;if(runner!=null)runner.Invalidate();appliedSummary.Text=runner!=null?"설정 또는 선택 항목이 변경됐습니다.\r\n환경설정을 다시 적용해야 시작할 수 있습니다.":"환경설정 미적용\r\n입력값과 상세시험을 확인한 뒤 적용하세요.";UpdateSelection();}
        void UpdateSelection(){if(Current==null)return;var selected=Selected();bool tim=Current.provider && selected.Contains("normal_tim");multi.Enabled=!busy && tim;if(!tim && multi.Checked)multi.Checked=false;start.Enabled=!busy && runner!=null && runner.Prepared;apply.Enabled=!busy && selected.Count>0 && address.Text.Trim().Length>0;start.BackColor=start.Enabled?Green:Color.FromArgb(219,223,216);start.ForeColor=start.Enabled?Color.White:Ink;stop.Enabled=busy || runner!=null;stop.Text=busy?"중지":"연결 해제";count.Text=completed.Count+" / "+selected.Count;report.Enabled=!busy && outcome!=null;folder.Enabled=!busy && lastDirectory!=null;review.Enabled=!busy && outcome!=null && outcome.Report!=null;next.Enabled=!busy && runner==null;}
        void SetBusy(bool value){busy=value;foreach(Control c in new Control[]{items,one,all,clear,settings})c.Enabled=!value;foreach(Control c in new Control[]{scenarios,web,address,paste})c.Enabled=!value && runner==null;UpdateSelection();}
        void Enqueue(Notice n){lock(queue)queue.Enqueue(n);}
        void Drain(){var notices=new List<Notice>();lock(queue){while(queue.Count>0)notices.Add(queue.Dequeue());}foreach(var n in notices){if(n.RunDirectory!=null)lastDirectory=n.RunDirectory;if(n.Kind=="stage" || n.Kind=="error" || n.Kind=="connection-error")status.Text=n.Text;if(n.Kind=="web-editing"){status.Text=n.Text;appliedSummary.Text="웹 입력값을 확인하고 있습니다.\r\n설정을 다시 적용한 뒤 시작하세요.";}if(n.Kind=="connection-error"||n.Kind=="web-editing")UpdateSelection();if(n.Kind=="web-configured"){
 loading=true;settings.LoadValues(n.Configuration);foreach(DataGridViewRow row in items.Rows)row.Cells[0].Value=n.Tests.Contains((string)row.Tag);if(!Current.provider || !n.Tests.Contains("normal_tim"))multi.Checked=false;loading=false;
 appliedSummary.Text=settings.Summary(Settings.Create(Current,n.Configuration,n.Tests,multi.Checked));status.Text="웹 설정 완료. 웹 또는 실행기에서 시험을 시작하세요.";UpdateSelection();
 }
 if(n.Kind=="web-starting"){completed.Clear();progress.Maximum=Math.Max(1,Selected().Count);progress.Value=0;tabs.SelectedIndex=1;SetBusy(true);status.Text=n.Text;}
 if(n.Kind=="run-finished"){outcome=runner==null?outcome:runner.Result;runner=null;SetBusy(false);status.Text=LabelState(n.Text)+" · 웹 결과에서 송수신과 판정 근거를 확인하세요.";if(closing)Close();}
 if(n.Kind=="log" && !String.IsNullOrWhiteSpace(n.Text)){log.AppendText(n.Text+Environment.NewLine);if(log.TextLength>90000)log.Text=log.Text.Substring(log.TextLength-60000);log.SelectionStart=log.TextLength;log.ScrollToCaret();}if(n.Kind=="state" && n.TestName!="MainScenario"){var key=n.TestName.StartsWith("test_")?n.TestName.Substring(5):n.TestName;foreach(DataGridViewRow r in items.Rows)if((string)r.Tag==key)r.Cells[2].Value=LabelState(n.State);if(new[]{"SUCCESS","FAIL","ERROR","STOPPED"}.Contains(n.State))completed.Add(key);progress.Value=Math.Min(progress.Maximum,completed.Count);count.Text=completed.Count+" / "+progress.Maximum;}}}
        static string LabelState(string state){switch(state){case "SUCCESS":return "성공";case "FAIL":return "실패";case "ERROR":return "수행 오류";case "STOPPED":return "중지";case "START":return "진행 중";default:return state;}}
        async Task ApplySettings(){if(busy)return;Settings value;try{Endpoint.Agent(address.Text,localTest);value=Settings.Create(Current,settings.Values(),Selected(),multi.Checked);}catch(Exception e){status.Text=InterfaceLogs.UserReport.PublicError(e);return;}if(runner!=null && !runner.Connected){runner.Dispose();runner=null;}SetBusy(true);try{if(runner==null){outcome=null;log.Clear();var scenario=Current;var url=address.Text;runner=new Runner(bundle,Enqueue,localTest);await Task.Run(()=>runner.Connect(scenario,url));}await Task.Run(()=>runner.Apply(value));Drain();appliedSummary.Text=settings.Summary(value);status.Text="설정 적용 완료. 확인 후 ‘시험 시작’을 누르세요.";}catch(Exception e){Drain();status.Text=InterfaceLogs.UserReport.PublicError(e);if(runner!=null && !runner.Connected){runner.Dispose();runner=null;}}finally{SetBusy(runner!=null && runner.Running);if(closing){if(runner!=null)runner.Dispose();runner=null;Close();}}}
        async Task StartRun(){if(busy || runner==null || !runner.Prepared)return;var selection=Selected();completed.Clear();outcome=null;foreach(DataGridViewRow r in items.Rows)r.Cells[2].Value=selection.Contains((string)r.Tag)?"대기":"미선택";progress.Maximum=selection.Count;progress.Value=0;tabs.SelectedIndex=1;SetBusy(true);try{outcome=await Task.Run(()=>runner.Start());Drain();status.Text=LabelState(outcome.Verdict)+" · 웹 결과에서 메시지와 판정 근거를 확인하세요.";}catch(Exception e){Drain();status.Text="시험을 완료하지 못했습니다. "+InterfaceLogs.UserReport.PublicError(e);}finally{if(runner!=null)runner.Dispose();runner=null;appliedSummary.Text="이 회차의 실행을 종료했습니다. 다음 시험은 새 회차로 진행하세요.";SetBusy(false);if(closing)Close();}}
        void MarkReviewed(){if(outcome==null || outcome.Report==null)return;J.Write(Path.Combine(outcome.RunDirectory,"manual-review.json"),new {scenario=outcome.ScenarioId,tests=outcome.Tests,reviewedAt=DateTimeOffset.Now.ToString("o"),meaning="사용자가 결과 확인 완료 버튼을 누름; 자동 판정과 별개"});ReadReviews();status.Text="직접 확인한 항목으로 기록했습니다. 다음 항목을 선택할 수 있습니다.";}
        void ReadReviews(){var checkedKeys=new HashSet<string>();var root=Path.Combine(bundle,"runs");if(Directory.Exists(root))foreach(var path in Directory.GetFiles(root,"manual-review.json",SearchOption.AllDirectories)){try{var row=J.Decode<Dictionary<string,object>>(J.Read(path));if(J.Number(row,"scenario")==Current.id)foreach(var key in J.List(J.Get(row,"tests")))checkedKeys.Add(Convert.ToString(key));}catch{}}foreach(DataGridViewRow r in items.Rows)r.Cells[3].Value=checkedKeys.Contains((string)r.Tag)?"확인 완료":"미확인";history.Text="직접 결과를 확인한 항목  "+checkedKeys.Count+" / "+Current.tests.Count;}
        void NextItem(){var rows=items.Rows.Cast<DataGridViewRow>().ToList();int index=items.CurrentRow==null?-1:items.CurrentRow.Index;var row=rows.Skip(index+1).FirstOrDefault(r=>Convert.ToString(r.Cells[3].Value)!="확인 완료")??rows.FirstOrDefault(r=>Convert.ToString(r.Cells[3].Value)!="확인 완료");if(row==null){status.Text="이 시험의 모든 항목에 직접 확인 표시가 있습니다.";return;}items.CurrentCell=row.Cells[1];SetSelection(new[]{(string)row.Tag});address.Clear();outcome=null;lastDirectory=null;completed.Clear();progress.Value=0;UpdateSelection();status.Text="웹에서 새 시험 회차를 열어 주소를 복사하세요.";}
        async void OnClosing(object sender,FormClosingEventArgs e){if(!busy){if(runner!=null)runner.Dispose();runner=null;return;}e.Cancel=true;if(closing)return;closing=true;status.Text="시험을 중지하고 실행 도구를 정리한 뒤 닫습니다.";if(runner!=null)await runner.Stop();}
        void OpenChrome(string target){try{var paths=new[]{Convert.ToString(Registry.GetValue(@"HKEY_LOCAL_MACHINE\SOFTWARE\Microsoft\Windows\CurrentVersion\App Paths\chrome.exe","",null)),Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles),@"Google\Chrome\Application\chrome.exe"),Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFilesX86),@"Google\Chrome\Application\chrome.exe"),Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),@"Google\Chrome\Application\chrome.exe")};var exe=paths.FirstOrDefault(File.Exists);if(exe==null)throw new IOException("Chrome 설치를 확인하세요.");var url=File.Exists(target)?new Uri(target).AbsoluteUri:target;Process.Start(new ProcessStartInfo(exe,'"'+url+'"'){UseShellExecute=false});}catch(Exception e){status.Text="화면을 열지 못했습니다. "+InterfaceLogs.UserReport.PublicError(e);}}
        public void CheckUi(string path){Show();Application.DoEvents();int total=0;foreach(var s in catalog.scenarios){scenarios.SelectedItem=s;Application.DoEvents();if(items.Rows.Count!=s.tests.Count || Selected().Count!=1 || start.Enabled)throw new Exception("초기 선택/시작 상태 불일치");SetSelection(s.tests.Where(t=>!s.provider || t.key!="no_data_error"&&t.key!="no_data").Select(t=>t.key));var valid=Settings.Create(s,settings.Values(),Selected(),false);if(valid.Port<1)throw new Exception("설정 검사 실패");if(s.provider){SetSelection(new[]{"no_data_error"});var absence=Settings.Create(s,settings.Values(),Selected(),false);if(absence.DataState!="absent")throw new Exception("자료 부재 조건 불일치");SetSelection(new[]{"no_data"});var empty=Settings.Create(s,settings.Values(),Selected(),false);if(empty.DataState!="empty")throw new Exception("빈 정상응답 조건 불일치");}SetSelection(new[]{s.tests[0].key});address.Text="wss://106.250.189.37:8443/ws/test/agent/999999/";if(start.Enabled || !apply.Enabled)throw new Exception("설정 적용 전 시작 차단 실패");address.Clear();total+=s.tests.Count;}J.Write(path,new {scenarios=catalog.scenarios.Count,items=total,checks="선택/적용 전 시작 차단/네이티브 설정 검사/자료 조건 분리",networkRequests=0});Close();}
        public void Render(string path,int width,int height){ClientSize=new Size(width,height);Show();Application.DoEvents();using(var bmp=new Bitmap(Width,Height)){DrawToBitmap(bmp,new Rectangle(Point.Empty,Size));bmp.Save(path);}Close();}
        public async Task CheckFlow(string url,string evidence){
            scenarios.SelectedItem=catalog.scenarios.Single(s=>s.id==51);SetSelection(new[]{"normal_utic"});address.Text=url;
            if(start.Enabled || !apply.Enabled)throw new Exception("설정 적용 전 버튼 상태 오류");
            await ApplySettings();if(!start.Enabled)throw new Exception("설정 적용 후 시작 불가: "+status.Text);
            await Task.Delay(1000);if(File.Exists(Path.Combine(runner.RunDirectory,"sut-process.json")))throw new Exception("설정 적용만으로 상대 실행됨");
            settings.SetValue("repetitions","11");
            if(start.Enabled)throw new Exception("수정 후 시작 버튼이 활성 상태");await ApplySettings();if(!start.Enabled)throw new Exception("설정 재적용 후 시작 불가: "+status.Text);
            await StartRun();if(outcome==null || outcome.Verdict!="SUCCESS")throw new Exception("UI 경유 실행 실패: "+status.Text);
            J.Write(evidence,new {appliedBeforeStart=true,editInvalidatedStart=true,reappliedBeforeStart=true,verdict=outcome.Verdict,run=outcome.RunDirectory,selected=outcome.Tests});
        }
    }
